import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-03-05 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-03-05 -- Ceph Performance Meeting","date":"2020-03-05T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","CRUSH 算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-05_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-03-05_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-03-05_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,u,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2020年3月5日" tabindex="-1">会议时间：2020年3月5日 <a class="header-anchor" href="#会议时间-2020年3月5日" aria-label="Permalink to &quot;会议时间：2020年3月5日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>性能优化更新</strong></p><ul><li>本周没有太多新的或更新的性能相关的Pull Requests (PRs)，团队主要集中在为下一个版本Octopus的修复工作上。</li><li>关闭的PR包括： <ul><li>对BlueStore的NVMe设备后端的小优化，移除了不必要的操作。</li><li>Igor提交的一个小PR，增加了日志分配统计，用于4K Metallic大小测试。</li><li>Casey合并的PR，允许修改配置索引卡，主要改变了默认的桶索引分片数量，以提高列表桶索引的速度。</li></ul></li></ul></li><li><p><strong>IO 500测试进展</strong></p><ul><li>继续进行SELinux测试与IO 500评分提升工作。</li><li>发现内核客户端在大尺寸读取时性能较慢，Fuse客户端也因多种原因性能极差。</li><li>开发了一个后端用于IOR和MD测试，直接与Loops FFS集成，初步结果显示在大尺寸顺序读取上显著更快。</li></ul></li><li><p><strong>PG日志更新优化</strong></p><ul><li>讨论了移除PG日志调用的实验，结果显示延迟显著降低，IOPS每核心有所提升。</li><li>建议将PG日志更新从BlueStore移至其他不引起大量光放大的地方。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续优化和测试IO 500性能，特别是比较内核客户端和Loops FFS的性能。</li><li>进一步研究和实施PG日志更新的优化策略。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续关注和处理性能相关的PRs。</li><li>完成IO 500测试，并根据结果调整策略。</li><li>实施PG日志更新的优化，并监测其对性能的影响。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了使用不同客户端（如Fuse和Loops FFS）的性能差异及其原因。</li><li>探讨了未来可能尝试的其他用户空间文件系统内核模块。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，团队成员将继续专注于各自的任务，并计划下周再次会议。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码优化建议，需要进一步的技术文档和代码审查来确保实施的正确性和有效性。</li></ul>',15)])])}const p=a(r,[["render",o]]);export{c as __pageData,p as default};
